p10.rule:
.$C .item:hover .item-x { animation-name: $C-fade; }
.$C .item-x { animation-duration: 1s; animation-fill-mode: forwards; animation-play-state: running; }
@keyframes $C-fade { to { opacity: 0; } }

q2.rule:
.$C .item-a { rotate: 8deg; }
.$C .item-a:hover { animation: $C-r8 1s infinite; animation-composition: add; }
@keyframes $C-r8 { to { rotate: 8deg; } }

n7.rule:
.$C .item-b { color: transparent; }
.$C .item-n { color: #fff; }
.$C .item-b::after { content: ''; display: block; position: relative; left: 160px; top: -24px; width: 120px; height: 40px; background: currentColor; }
.$C .item:hover .item-b { color: #000; }

.$C .item-b::after { content: ''; display: block; position: relative; left: 160px; top: -24px; width: 120px; height: 40px; box-shadow: inset 0 0 0 60px currentColor; }
.$C .item-b { color: transparent; }
.$C .item-n { color: #fff; }
.$C .item:hover .item-b { color: #000; }

m8.rule:
.$C .mark-shelf { display: block; position: relative; outline: 8px solid transparent; }
.$C .mark-shelf { outline-offset: 8px; }
.$C .items:hover .mark-shelf { outline-color: #000; }

.$C .mark-shelf { display: block; position: relative; outline-width: 8px; }
.$C .stall .mark-shelf { outline-offset: 8px; outline-style: solid; outline-color: transparent; }
.$C .items:hover .mark-shelf { outline-color: #000; }

.$C .item-b { position: relative; color: transparent; text-shadow: 300px 0 0; }
.$C .item-n { color: #fff; }
.$C .item:hover .item-b { color: #000; }

@keyframes $C-ring { 0%, 100% { outline-width: 200px; outline-offset: -100px; } }
.$C .item-b { outline: 1px solid transparent; animation: $C-ring 1s infinite; }
.$C .item:hover .item-b { outline-color: #000; }
